// Deferred Naukri command transactions on fictional PostgreSQL. No Telegram/browser network.
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_naukri_pause_fences_unknown_writes_without_refunding_spent_budget(){
 let mut c=browser_fixture().await;execution_seed_policy(&mut c).await;let(settings,identity)=telegram_question_binding(&mut c).await;let work=execution_work(&mut c,"APPLYING","executing","apply").await;let quota=json!({"reservations":["spent-one","spent-two","spent-three"]});browser_save(&mut c,"apply_budget:naukri:retained",quota.clone()).await;assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(200,"/naukri queue pause")).await.unwrap());let current=browser_pref(&mut c,&work).await;assert_eq!(current["stage"],"SUBMISSION_UNKNOWN");assert_eq!(current["admitted_actions"],json!([{"fingerprint":"apply:retained-spent"}]));assert_eq!(browser_pref(&mut c,"application_queue_policy").await["state"],"PAUSED");assert_eq!(browser_pref(&mut c,"apply_budget:naukri:retained").await,quota);let before=browser_snapshot(&mut c).await;assert!(!telegram_answer_update(&mut c,&settings,&identity,telegram_update(200,"/naukri queue pause")).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_naukri_add_deduplicates_requisition_and_never_echoes_private_query(){
 let(mut c,_job)=packet_service_fixture().await;execution_running(&mut c).await;let(settings,identity)=telegram_question_binding(&mut c).await;let add="/naukri add https://www.naukri.com/job-listings-fictional-923456789012?private_token=PRIVATE_QUERY_CANARY";assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(210,add)).await.unwrap());let rows:Vec<Value>=sqlx::query_scalar("SELECT value FROM owner_preferences WHERE starts_with(key,'apply_work:') AND value->>'requisition'='923456789012'").fetch_all(&mut c).await.unwrap();assert_eq!(rows.len(),1);let work=rows[0].clone();assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(211,"/naukri add https://naukri.com/job-listings-other-slug-923456789012")).await.unwrap());assert_eq!(browser_pref(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap())).await,work);let replies:Vec<String>=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries WHERE update_id IN (210,211)").fetch_all(&mut c).await.unwrap();assert_eq!(replies.len(),2);assert!(replies.iter().all(|s|!s.contains("PRIVATE_QUERY_CANARY")&&!s.contains("private_token")));assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_naukri_apply_means_preparation_and_execution_controls_leave_application_queue_policy_unchanged(){
 let(mut c,jobs)=legacy_schedule_fixture().await;let(settings,identity)=telegram_question_binding(&mut c).await;let queue=browser_pref(&mut c,"application_queue_policy").await;let text=format!("/naukri apply {}",jobs[0]);assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(220,&text)).await.unwrap());let intent:Value=sqlx::query_scalar("SELECT value FROM owner_preferences WHERE starts_with(key,'exec:')").fetch_one(&mut c).await.unwrap();assert_eq!(intent["state"],"DISCOVERED");let id=intent["id"].as_str().unwrap();for(index,action)in ["pause","resume","cancel"].iter().enumerate(){assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(221+index as i64,&format!("/naukri {action} {id}"))).await.unwrap());}assert_eq!(browser_pref(&mut c,&format!("exec:{id}")).await["state"],"FAILED_FINAL");assert_eq!(browser_pref(&mut c,"application_queue_policy").await,queue);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_packets WHERE job_id=$1").bind(jobs[0]).fetch_one(&mut c).await.unwrap(),0);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_naukri_status_read_does_not_take_owner_lock_and_wrong_bot_command_is_inert(){
 let(mut c,_job)=packet_service_fixture().await;execution_seed_policy(&mut c).await;let(settings,identity)=telegram_question_binding(&mut c).await;browser_save(&mut c,"agent_conversation:primary",json!({"retain":"owner"})).await;let before=browser_snapshot(&mut c).await;let mut owner=connection().await;let mut tx=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *tx).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(230,"/naukri status")).await.unwrap());assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(231,"/naukri@wrong_bot queue start")).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);tx.rollback().await.unwrap();let replies:Vec<String>=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries ORDER BY update_id").fetch_all(&mut c).await.unwrap();assert!(replies[0].contains("Naukri queue:"));assert!(replies[1].starts_with("/naukri add"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_naukri_automatic_start_rejection_rolls_back_command_but_advances_update_cursor(){
 let(mut c,_binding,_profile)=sync_fixture(json!([])).await;let(settings,identity)=telegram_question_binding(&mut c).await;let mut config=browser_pref(&mut c,"application_queue_policy").await;config["state"]=json!("STOPPED");config["policy"]["platforms"]["naukri"]["mode"]=json!("AUTOMATIC");browser_save(&mut c,"application_queue_policy",config.clone()).await;let before=browser_snapshot(&mut c).await;assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(240,"/naukri queue start")).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(browser_pref(&mut c,"application_queue_policy").await,config);let reply:String=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries WHERE update_id=240").fetch_one(&mut c).await.unwrap();assert!(reply.contains("automatic_first_verified_worker_receipt_required"));assert_eq!(sqlx::query_scalar::<_,i64>("SELECT next_update_id FROM agent_telegram_state WHERE key='primary'").fetch_one(&mut c).await.unwrap(),241);
}
